window.__WIKI_PAGES = window.__WIKI_PAGES || {};
window.__WIKI_PAGES["code-effects"] = [
"@subtitle: 注册效果定义，声明即时、开始、每 tick 与结束四个阶段的可选回调。",
"",
"## 契约",
"",
"<table>",
"  <thead><tr><th>项</th><th>内容</th></tr></thead>",
"  <tbody>",
"    <tr><td>调用</td><td><code>require(\"core:systems.effects\").register_definition(effect_id, definition)</code></td></tr>",
"    <tr><td>执行端</td><td>权威使用在 Server；函数体本身**不检查**逻辑端。</td></tr>",
"    <tr><td>生命周期</td><td>定义模块装入时有内置登记。函数没有按候选／发布／保存／加载／卸载分支拒绝；能否被其他 Mod <code>require</code> 取决于模块可见性。</td></tr>",
"    <tr><td>参数</td><td><code>effect_id</code> 为非空字符串，不强制命名空间；<code>definition</code> 为表，可选 <code>instant</code>、<code>modifier_start</code>、<code>modifier_tick</code>、<code>modifier_end</code>，每项存在时必须是函数。</td></tr>",
"    <tr><td>返回与失败</td><td>成功返回 true；参数无效返回 false 并保留已有定义，修正后可重试。注册保存的是传入的表对象本身。</td></tr>",
"    <tr><td>重复与覆盖</td><td>相同 ID 直接替换。</td></tr>",
"    <tr><td>注销</td><td><code>clear_runtime</code> 清效果组与收据，**不清 definitions**；未见专用注销接口。</td></tr>",
"    <tr><td>消费方</td><td>CoreMod 的效果系统查定义并运行各阶段回调；无定义会作为独立配置问题报告。</td></tr>",
"  </tbody>",
"</table>",
"",
"## 注册示例",
"",
"### 最小示例",
"",
"只给即时回调也能注册：",
"",
"~~~lua",
"local effects = require(\"core:systems.effects\")",
"",
"effects.register_definition(\"example:heal\", {",
"  instant = function(ctx) return true end",
"})",
"~~~",
"",
"### 完整示例",
"",
"四个阶段都提供：",
"",
"~~~lua",
"local effects = require(\"core:systems.effects\")",
"",
"effects.register_definition(\"example:regen\", {",
"  instant = function(ctx) return true end,",
"  modifier_start = function(ctx) return true end,",
"  modifier_tick = function(ctx) return true end,",
"  modifier_end = function(ctx) return true end",
"})",
"~~~",
"",
"## 注意事项",
"",
"### 返回 false 不等于失败",
"",
"<code>register_definition</code> 返回 <code>false</code> 表示参数无效；而回调返回 <code>false</code> 是运行时语义（是否接受）。两者不要混淆。",
"",
"### 覆盖是替换而不是合并",
"",
"同 ID 再登记会直接替换整份定义，后注册的四项回调不会与旧的合并。"
];
